#include <WiFi.h>
#include <WebServer.h>
#include <ESPmDNS.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;
WebServer server(80);

// ===== Список сетей: имя и пароль идут парами =====
const char* WIFI_SSIDS[] = {"KIBERone5", "KIBERone"};
const char* WIFI_PASSS[] = {"KIBERone", "KIBERone"};
const int   WIFI_COUNT   = sizeof(WIFI_SSIDS) / sizeof(WIFI_SSIDS[0]);

const int CHAR_DELAY  = 60;   // пауза между символами, мс
const int TYPE_DELAY  = 1000; // пауза перед началом набора, мс

volatile bool pending = false;
String payloadText = "";

void connectWiFi() {
  Serial.println("Сканирую сети...");
  int n = WiFi.scanNetworks();
  if (n <= 0) { Serial.println("Сети не найдены!"); return; }

  for (int i = 0; i < n; i++) {
    String found = WiFi.SSID(i);
    for (int j = 0; j < WIFI_COUNT; j++) {
      if (found == WIFI_SSIDS[j]) {
        Serial.printf("Найдена \"%s\", подключаюсь...\n", WIFI_SSIDS[j]);
        WiFi.begin(WIFI_SSIDS[j], WIFI_PASSS[j]);
        unsigned long start = millis();
        while (WiFi.status() != WL_CONNECTED && millis() - start < 15000) {
          delay(500);
          Serial.print(".");
        }
        Serial.println();
        if (WiFi.status() == WL_CONNECTED) return;
        Serial.println("Не подключилось, пробую следующую сеть.");
      }
    }
  }
  Serial.println("Ни одна сеть не подключилась.");
}

// ===== Скрипт для консоли тренажёра (IP подставится автоматически) =====
const char* SCRIPT_JS = R"rawliteral(
(async () => {
  const IP = '%IP%';
  const send = t => fetch('http://' + IP + '/type?text=' + encodeURIComponent(t)).catch(()=>{});
  const key  = k => fetch('http://' + IP + '/key?k=' + k).catch(()=>{});

  const NOISE = /stamina|поддержите|настройка|конфиденциальность|условия|теория|регистрация|расскажите/i;

  function findPhrase() {
    let best = null;
    for (const el of document.querySelectorAll('div, section, p, pre, span')) {
      const t = (el.innerText || '').trim();
      if (t.length < 30 || t.length > 6000 || NOISE.test(t)) continue;
      if (!best || t.length > best.length) best = t;
    }
    return best;
  }

  let lastSent = null;

  // Старт: жмём Space, сайт начинает урок
  key('space');
  await new Promise(r => setTimeout(r, 1500));

  const tick = () => {
    const phrase = findPhrase();
    if (phrase && phrase !== lastSent) {
      lastSent = phrase;
      console.log('%c ESP32:', 'color:green', 'отправляю фразу:', phrase.slice(0, 60) + '...');
      send(phrase);
    }
  };

  setInterval(tick, 2000);
  tick();
  console.log('Скрипт запущен. Следит за фразами и отправляет их на ESP32 (' + IP + ')');
})();
)rawliteral";

