void typeText(String text) {
  for (unsigned int i = 0; i < text.length(); i++) {
    char c = text[i];
    if (c == '\n') { Keyboard.press(KEY_RETURN); Keyboard.releaseAll(); }
    else Keyboard.write(c);
    delay(CHAR_DELAY);
  }
}

void handleRoot() { server.send(200, "text/html", PAGE_HTML); }

void handleScript() {
  String js = SCRIPT_JS;
  js.replace("%IP%", WiFi.localIP().toString());
  server.send(200, "text/plain", js);
}

void handleType() {
  if (server.hasArg("text")) {
    payloadText = server.arg("text");
    pending = true;
    server.send(200, "text/plain", "OK");
  } else {
    server.send(400, "text/plain", "нет параметра text");
  }
}

void handleKey() {
  String k = server.arg("k");
  if (k == "space") { Keyboard.press(' '); Keyboard.releaseAll(); }
  else if (k == "enter") { Keyboard.press(KEY_RETURN); Keyboard.releaseAll(); }
  else if (k == "winr") {
    Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
    delay(120); Keyboard.releaseAll();
  }
  server.send(200, "text/plain", "OK");
}

void setup() {
  Serial.begin(115200);

  Keyboard.begin();
  USB.begin();
  delay(2000);   // время системе распознать клавиатуру

  WiFi.mode(WIFI_STA);
  connectWiFi();

  if (MDNS.begin("esp32kbd")) {
    Serial.println("mDNS запущен: http://esp32kbd.local");
  }

  server.on("/", handleRoot);
  server.on("/script", handleScript);
  server.on("/type", handleType);
  server.on("/key", handleKey);
  server.begin();

  // ===== Красивая сводка в Serial =====
  Serial.println();
  Serial.println("========================================");
  Serial.println("  ESP32 WiFi Keyboard готова!");
  Serial.println("========================================");
  Serial.print("  Управление:  http://");
  Serial.println(WiFi.localIP());
  Serial.print("  Скрипт:      http://");
  Serial.print(WiFi.localIP());
  Serial.println("/script");
  Serial.println("  (или просто http://esp32kbd.local)");
  Serial.println("========================================");
}

void loop() {
  server.handleClient();

  // Переподключение при обрыве
  if (WiFi.status() != WL_CONNECTED) {
    static unsigned long lastTry = 0;
    if (millis() - lastTry > 30000) { lastTry = millis(); connectWiFi(); }
  }

  // Автонажатие: как только пришёл текст — печатаем сами, без кнопки
  if (pending) {
    pending = false;
    Serial.print("Печатаю: ");
    Serial.println(payloadText.substring(0, 40));
    delay(TYPE_DELAY);
    typeText(payloadText);
    Serial.println("Готово");
  }

  delay(10);
}
